import{_ as i,a0 as t,w as o,s as d,ao as c,I as p,x as a,a1 as e,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Linux 上使用 Bash 自動化任務 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上使用 Bash 自動化任務 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上使用 Bash 自動化任務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上使用 Bash 自動化任務 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220726 How I use Bash to automate tasks on Linux","title":"如何在 Linux 上使用 Bash 自動化任務","tag":"202208","desc":""},"relativePath":"202208/20220726 How I use Bash to automate tasks on Linux.md","filePath":"[post].md"}'),r={name:"202208/20220726 How I use Bash to automate tasks on Linux.md"};function h(g,s,f,u,k,b){const n=t("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-linux-上使用-bash-自動化任務" tabindex="-1">如何在 Linux 上使用 Bash 自動化任務 <a class="header-anchor" href="#如何在-linux-上使用-bash-自動化任務" aria-label="Permalink to “如何在 Linux 上使用 Bash 自動化任務”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/30/181814f4v7ahztuaaxwqwg.jpg" alt=""></p><blockquote><p>Bash 有一些方便的自動化功能，可以讓我在 Linux 上處理文件時更輕鬆。</p></blockquote><p>通過 Bash 命令列進行自動化任務是極好的一種方式。不論你使用運行在服務器上的 Linux 進行管理日誌文件或其他文件，還是你在個人電腦上整理文件以使桌面保持整潔，使用 Bash 的自動化功能會使你的工作變得更輕鬆。</p><h3 id="自動執行文件任務-for" tabindex="-1">自動執行文件任務：for <a class="header-anchor" href="#自動執行文件任務-for" aria-label="Permalink to “自動執行文件任務：for”">​</a></h3><p>如果你對一堆文件要同時處理，並且對每個文件進行相同的操作，請使用 <code>for</code> 命令。該命令會遍歷文件列表，並執行一個或多個命令。<code>for</code> 命令如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for 變量 in 列表</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>我在示例中添加了額外的空白和換行，來分開 <code>for</code> 命令中不同的部分。看起來好像無法在命令列中同時運行多個命令，不過你可以使用 <code>;</code> 將所有命令放在同一行中，就像這樣:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for 變量 in 列表 ; do 命令 ; done</span></span></code></pre></div><p>讓我們看看它的實際效果。我使用 <code>for</code> 命令來重命名一些文件。最近，我有一些截圖，想要重命名。這些截圖名稱為 <code>filemgr.png</code> 或 <code>terminal.png</code>，我想將 <code>screenshot</code> 放在每個名稱前。我可以使用 <code>for</code> 命令一次性將 30 個文件重命名。這是兩個文件的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>filemgr.png  terminal.png</span></span>
<span class="line"><span>$ for f in *.png ; do mv $f screenshot-$f ; done</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>screenshot-filemgr.png  screenshot-terminal.png</span></span></code></pre></div><p><code>for</code> 命令使得在一系列文件中執行一種或多種操作變得容易。你可以用一些有意義的變量名，比如 <code>image</code> 或 <code>screenshot</code>，或者你用示例中“縮寫的”變量 <code>f</code>。當我在使用 <code>for</code> 循環寫腳本的時候，會選擇有意義的變量名。但是當我在命令列中使用 <code>for</code>，我通常會選擇縮寫變量名，比如 <code>f</code> 代表文件，<code>d</code> 代表目錄等。</p><p>不論你選擇怎樣的變量名，請確保在引用變量時添加 <code>$</code> 符號。這會將變量擴展為你正在處理的文件的名稱。在 Bash 提示符下鍵入 <code>help for</code> 以瞭解有關 <code>for</code> 命令的更多信息。</p><h3 id="按條件執行-if" tabindex="-1">按條件執行：if <a class="header-anchor" href="#按條件執行-if" aria-label="Permalink to “按條件執行：if”">​</a></h3><p>當你需要對每個文件執行相同操作時，使用 <code>for</code> 循環遍歷一些文件很有幫助。但是，如果你需要對某些文件做一些不同的事情怎麼辦？為此，你需要使用 <code>if</code> 語句進行條件執行。<code>if</code> 語句如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 測試</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>你也可以使用 <code>if</code>、<code>else</code> 語句進行判斷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 測試</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>你可以使用 <code>if</code>、<code>elif</code>、<code> else</code> 語句來實現更復雜的程序。當我一次性需要自動處理很多文件時，我會在腳本中使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if 測試1</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>elif 測試2</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>elif 測試3</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    命令</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p><code>if</code> 命令可以讓你進行各種判斷，例如判斷一個文件是否是一個文件，或者一個文件是否為空文件（零字節）。在命令列中輸入 <code>help test</code>，可以立即查看使用 <code>if</code> 語句能夠進行的各種測試。</p><p>例如，假設我想清理一個包含幾十個文件的日誌目錄。日誌管理中的一個常見任務是刪除所有空日誌文件，並壓縮其他日誌。解決這個問題的最簡單方法是刪除空文件。沒有可以完全匹配的 <code>if</code> 測試，但是我們有 <code>-s</code> 選項來判斷是否是一個文件，並且判斷該文件不是空的（大小不為零）。這與我們想要的相反，但我們可以使用 <code>!</code> 來否定測試，以判斷某些內容不是文件或為空。</p><p>讓我們用一個示例來看看這個過程。我創建了兩個測試文件：一個是空的，另一個包含一些數據。我們可以使用 <code>if</code> 判斷，<em>如果</em>文件為空打印消息 <code>empty</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>datafile  emptyfile</span></span>
<span class="line"><span>$ if [ ! -s datafile ] ; then echo &quot;empty&quot; ; fi</span></span>
<span class="line"><span>$ if [ ! -s emptyfile ] ; then echo &quot;empty&quot; ; fi</span></span>
<span class="line"><span>empty</span></span></code></pre></div><p>我們可以將 <code>if</code> 和 <code>for</code> 命令結合起來，檢查日誌文件列表中的空文件並刪除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 20</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  1 01:02 log.1</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  2 01:02 log.2</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  3 01:02 log.3</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 0 Jul  4 01:02 log.4</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  5 01:02 log.5</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 0 Jul  6 01:02 log.6</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  7 01:02 log.7</span></span>
<span class="line"><span>$ for f in log.* ; do if [ ! -s $f ] ; then rm -v $f ; fi ; done</span></span>
<span class="line"><span>removed &#39;log.4&#39;</span></span>
<span class="line"><span>removed &#39;log.6&#39;</span></span>
<span class="line"><span>$ ls -l</span></span>
<span class="line"><span>total 20</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  1 01:02 log.1</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  2 01:02 log.2</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  3 01:02 log.3</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  5 01:02 log.5</span></span>
<span class="line"><span>-rw-rw-r--. 1 jhall jhall 2 Jul  7 01:02 log.7</span></span></code></pre></div><p>使用 <code>if</code> 命令可以在需要時執行一些操作，使腳本變得智能。我經常會在腳本中使用 <code>if</code>，當我需要判斷文件在我的系統上存在或不存在時，或者判斷腳本正在檢查的條目是文件或目錄時。使用 <code>if</code> 使得腳本能夠根據需要採取不同的操作。</p><hr>`,28)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/22/7/use-bash-automate-tasks-linux"},{default:l(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/22/7/use-bash-automate-tasks-linux",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/jim-hall"},{default:l(()=>[...s[2]||(s[2]=[a("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lkxed"},{default:l(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/Donkey-Hao"},{default:l(()=>[...s[4]||(s[4]=[a("Donkey-Hao",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:l(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=i(r,[["render",h]]);export{w as __pageData,y as default};
